        if(i<n && (s.charAt(i)=='-' || s.charAt(i)=='+')) {
            if(s.charAt(i)=='-')sign = -1;
            i++;
        } 

        return recur(s, i, 0, sign);

    }

    private int recur(String s, int i, int ans, int sign){
        if(i>=s.length()) return ans*sign;
        char c = s.charAt(i);
        if(!(s.charAt(i)>='0' && s.charAt(i) <='9')) return ans*sign;
        int digit = c - '0';
        if(ans> (Integer.MAX_VALUE - digit)/10){
                return sign==1? Integer.MAX_VALUE : Integer.MIN_VALUE;
            } 
        ans = ans*10 + digit;
        return recur(s, i+1, ans, sign);
    }
}
